-- Round 7, Branch B (Keenan, 2026-11-08): the deck's words and the light
-- picker's looks, seeded from the five-seat debate (docs/decisions.md,
-- 2026-11-08), only while nothing has been saved there yet. Edited in
-- Settings. The live deck reads settings.presentation, so nothing a customer
-- sees changes until Keenan says "push the changes".

update public.settings
   set deck = $deck${"version": 1, "pages": {"what_vesper_is": {"headline": "Up once, there all year", "words": "A slim track under the edge of your roof, with the lights built in. Nothing to hang every fall.", "more_label": "What's in it", "more_text": "The lights sit in a slim aluminum track, about 8 inches apart, tucked under the soffit, the underside of your roof's edge.\nEach light has red, green and blue, plus its own white.\nA control box plugs into a standard outlet.\nYou run it from an app on your phone, over your home Wi-Fi."}, "hidden_by_day": {"headline": "Hidden by day", "words": "The track tucks under the soffit. By day you see your house. By night you choose the light.", "more_label": "Up close", "more_text": "The track tucks under the soffit, where it's hard to spot by day. White track is in stock. Other colours are made to order. If your community has guidelines, we're happy to answer questions."}, "whites_first": {"headline": "Warm white, most nights", "words": "Every light has its own white, so white looks clean. Colour is there for the nights you want it.", "more_label": "Warm or cool", "more_text": "Warm white is soft, like a porch light. Cool white is closer to daylight. Pick either one, any night, from your phone."}, "light_picker": {"headline": "Try it on your house", "words": "A preview drawn on our photo of your house. Tap a look.", "more_label": "", "more_text": ""}, "phone_control": {"headline": "Run it from your phone", "words": "Pick a look in the app and your house changes. We set up the app with you on install day.", "more_label": "What the app does", "more_text": "Turn the lights on or off and change the look from your phone. It works over your home Wi-Fi."}, "gallery": {"headline": "Homes we've lit", "words": "", "more_label": "See all", "more_text": ""}, "install_day": {"headline": "How install day works", "words": "We confirm the plan and the colours with you.\nA small crew fits the track and plugs in the control box.\nWe clean up and set up the app with you.", "more_label": "What we'll need", "more_text": "An outlet near where the control box will go, in the garage or outside.\nYour Wi-Fi name and password, so we can set up the app with you."}, "warranty": {"headline": "Our 10-year warranty", "words": "", "more_label": "The full warranty", "more_text": ""}, "mockup": {"headline": "Where your lights would go", "words": "", "more_label": "", "more_text": ""}}, "warranty_lines_up_front": 3}$deck$::jsonb,
       light_looks = $looks$[{"key": "warm_white", "name": "Warm white", "words": "Like a porch light", "colours": [{"hex": "#FFB46B", "name": "Warm white"}], "block": 1, "active": true}, {"key": "cool_white", "name": "Cool white", "words": "Like daylight", "colours": [{"hex": "#E4EEFF", "name": "Cool white"}], "block": 1, "active": true}, {"key": "christmas", "name": "Christmas", "words": "Red, green, white", "colours": [{"hex": "#FF2D20", "name": "Red"}, {"hex": "#16C83C", "name": "Green"}, {"hex": "#FFB46B", "name": "Warm white"}], "block": 3, "active": true}, {"key": "game_night", "name": "Game night", "words": "Red and gold", "colours": [{"hex": "#FF2A1F", "name": "Red"}, {"hex": "#FFB000", "name": "Amber"}], "block": 3, "active": true}, {"key": "halloween", "name": "Halloween", "words": "Orange and purple", "colours": [{"hex": "#FF6A00", "name": "Orange"}, {"hex": "#8F3BFF", "name": "Purple"}], "block": 3, "active": true}]$looks$::jsonb
 where id = 1 and deck = '{}'::jsonb;
